// topic: zigdash/automation/autoclose/<id>/config
const parts = msg.topic.split('/');
const id = parts[3];
const rules = flow.get('rules') || {};
const timers = flow.get('timers') || {};
const raw = msg.payload;
const empty = raw === undefined || raw === null ||
    (typeof raw === 'string' && raw.trim() === '') ||
    (Buffer.isBuffer(raw) && raw.length === 0);
const stateTopic = `zigdash/automation/autoclose/${id}/state`;

function clearTimerFor(id) {
    if (timers[id]) { clearTimeout(timers[id]); delete timers[id]; }
}

if (empty) {
    clearTimerFor(id);
    delete rules[id];
    flow.set('rules', rules);
    flow.set('timers', timers);
    // Clear retained state topic too (no litter for deleted rules).
    return { topic: stateTopic, payload: '', retain: true };
}

const cfg = (typeof raw === 'object' && !Buffer.isBuffer(raw))
    ? raw
    : JSON.parse(raw.toString());

// A new/updated config cancels any in-flight timer for safety.
clearTimerFor(id);
rules[id] = cfg;
flow.set('rules', rules);
flow.set('timers', timers);

const status = cfg.enabled ? 'idle' : 'disabled';
return { topic: stateTopic, retain: true,
         payload: JSON.stringify({ enabled: !!cfg.enabled, status: status }) };

const rules = flow.get('rules') || {};
const timers = flow.get('timers') || {};
const lastValues = flow.get('lastValues') || {};
const topic = msg.topic;
let payload = msg.payload;
if (Buffer.isBuffer(payload)) payload = payload.toString();

let j;
try {
    j = (typeof payload === 'object') ? payload : JSON.parse(payload);
} catch (e) {
    return null; // ignore non-JSON
}

const out = [];

for (const id of Object.keys(rules)) {
    const cfg = rules[id];
    if (cfg.triggerTopic !== topic) continue;
    const path = cfg.triggerPath || 'state';
    const current = j != null ? j[path] : undefined;
    if (current === undefined) continue;
    const key = `${id}:${cfg.triggerTopic}`;
    const prev = lastValues[key];
    lastValues[key] = current;
    // Edge: prev != trigger, current == trigger.
    if (current !== cfg.triggerValue) continue;
    if (prev === cfg.triggerValue) continue;        // duplicate ON -> ignore
    if (!cfg.enabled) continue;
    if (timers[id]) continue;                       // Lock: first edge wins

    const stateTopic = `zigdash/automation/autoclose/${id}/state`;
    const delaySec = Math.max(1, Math.min(3600, Number(cfg.delaySeconds) || 60));
    const fireAt = new Date(Date.now() + delaySec * 1000).toISOString();

    // Publish 'pending' state.
    out.push({ topic: stateTopic, retain: true,
               payload: JSON.stringify({ enabled: true, status: 'pending',
                                          pendingCloseAt: fireAt }) });

    timers[id] = setTimeout(() => {
        // Re-read latest rule snapshot — config may have changed mid-flight.
        const rulesNow = flow.get('rules') || {};
        const cfgNow = rulesNow[id];
        delete timers[id];
        flow.set('timers', timers);
        if (!cfgNow || !cfgNow.enabled) return;
        const firedAt = new Date().toISOString();
        node.send([
            { topic: cfgNow.target, retain: false, payload: cfgNow.closePayload },
            { topic: stateTopic, retain: true,
              payload: JSON.stringify({ enabled: true, status: 'idle',
                                         lastFiredAt: firedAt }) }
        ]);
    }, delaySec * 1000);
}

flow.set('lastValues', lastValues);
flow.set('timers', timers);
return [out];
